{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "UK-224,671, a polar cyclopropylmethyl-containing drug, had only 7.5% oral bioavailability in humans in the fasted state, directly supporting low F for the similarly polar, cyclopropylmethyl-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Catechin had only about 1.68% oral bioavailability in humans, supporting low F for the phenolic query scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Epicatechin showed low oral bioavailability and poor absorption in humans, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "MK-458, a phenolic fused-ring amine, had approximately 5% absolute oral bioavailability in patients, supporting low F for the query's phenolic fused-ring amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Rotigotine, a phenolic aminotetralin, has low oral bioavailability in humans, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Dihydrexidine, a catechol-containing fused-ring amine, has low oral bioavailability and rapid metabolism, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Estradiol, a phenolic steroid, has absolute oral bioavailability of only about 1-5% in humans, supporting low F for the phenolic fused-ring query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Pethidine, a tertiary-amine opioid, has about 56% oral bioavailability in healthy subjects, which would support high F but is weakly transferable because the query is a permanently charged quaternary ammonium.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "Drospirenone has 76-85% oral bioavailability in humans, but it lacks the phenolic and quaternary-ammonium polarity of the query, so this high-F evidence is weakly transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted low: the query is a permanently charged quaternary ammonium morphinan with multiple polar groups, and the most transferable human oral bioavailability data (UK-224,671, catechins, MK-458, rotigotine, dihydrexidine, estradiol) all show F <20%. The moderate/high F analogues (pethidine, drospirenone) are structurally less relevant and do not overcome the consistent low-F evidence.",
  "evidence_gaps": [
    "No direct human or animal oral bioavailability measurement for the query molecule itself.",
    "No permeability or transporter (e.g., P-gp) data specific to the quaternary ammonium query.",
    "Potential effects of formulation, dose, or food on F are not captured by the analogue set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

